  amountCents: integer("amount_cents").notNull(),
  token: text("token").notNull().unique(),
  deliveryChannel: text("delivery_channel").notNull(),
  billingPeriodStart: timestamp("billing_period_start"),
  // What this invoice is for. "rent" is the default (recurring or one-off rent);
  // "charge" is a one-off non-rent bill (utilities, late fee, cleaning, damages, other).
  // chargeType carries the category, description the human-readable label shown to the tenant.
  kind: text("kind").notNull().default("rent"),
  chargeType: text("charge_type"),
  description: text("description"),
  status: text("status").notNull().default("pending_dispatch"),
  dueAt: timestamp("due_at").notNull(),
  dispatchedAt: timestamp("dispatched_at"),
  sentAt: timestamp("sent_at"),
  paidAt: timestamp("paid_at"),
  voidedAt: timestamp("voided_at"),
  externalPaymentReference: text("external_payment_reference"),
  lastReminderSentAt: timestamp("last_reminder_sent_at"),
  reminderCount: integer("reminder_count").notNull().default(0),
  windcaveSessionId: text("windcave_session_id"),
  windcaveTransactionId: text("windcave_transaction_id"),
  // Split-bill: the merchant enables it; the tenant chooses how many flatmates
  // share the rent on the checkout page. Each share is paid via the same link.
  splitEnabled: boolean("split_enabled").notNull().default(false),
  splitCount: integer("split_count"),                       // chosen number of ways (null until tenant splits)
  splitPaidCount: integer("split_paid_count").notNull().default(0),
  splitPaidSessions: text("split_paid_sessions").array(),   // Windcave session ids already counted (idempotency)
  splitPayerEmails: text("split_payer_emails").array(),     // emails collected from share payers (for GST copies)
  // WhatsApp delivery tracking: Evolution API message ID stored at send time;
  // whatsappDeliveredAt set when the DELIVERY_ACK webhook arrives.
  whatsappMessageId: text("whatsapp_message_id"),
  whatsappDeliveredAt: timestamp("whatsapp_delivered_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
}, (t) => ({
  scheduleBillingPeriodUnique: uniqueIndex("invoices_schedule_billing_period_unique")
